#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "gemm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec); // C: i x j  (dims: 'i','j'; j is the fast/contiguous dim)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // A: i x k  (dims: 'i','k'; k contiguous)
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ k_vec); // B: k x j  (dims: 'k','j'; j contiguous)
} tuning;

// Array initialization
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	// C: i x j
	// A: i x k
	// B: k x j
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Pre-compute lengths once; they are invariant in the traversals
	const std::size_t ni = C | get_length<'i'>();
	const std::size_t nk = A | get_length<'k'>();
	const std::size_t nj = B | get_length<'j'>();

	// C[i][j] = (i*j+1) % ni / ni
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 1) % ni) / (num_t)ni;
	});

	// A[i][k] = i*(k+1) % nk / nk
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)(i * (k + 1) % nk) / (num_t)nk;
	});

	// B[k][j] = k*(j+2) % nj / nj
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = (num_t)(k * (j + 2) % nj) / (num_t)nj;
	});
}

// Main computational kernel (GEMM)
// Form C := alpha*A*B + beta*C,
// A is NIxNK, B is NKxNJ, C is NIxNJ
//
// Optimized for data locality:
// - C: dims 'i','j'  (row-major, j contiguous)
// - A: dims 'i','k'  (k contiguous)
// - B: dims 'k','j'  (j contiguous)
//
// We use loop order i–k–j:
//
//   for i:
//     C[i,*] *= beta
//     for k:
//       tmp = alpha * A[i,k]           // reused for all j
//       for j:
//         C[i,j] += tmp * B[k,j]
//
// This makes the innermost loop traverse j, which is contiguous in both C and B,
// and reuses alpha*A[i,k] across all j, reducing the number of multiplications.
[[gnu::flatten, gnu::noinline]]
void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

#pragma scop
	// ---------------------------------------------------------------------
	// 1. Scale C by beta: C[i][j] *= beta
	// ---------------------------------------------------------------------
	traverser(C).for_each([=](auto state) {
		C[state] *= beta;
	});

	// ---------------------------------------------------------------------
	// 2. Accumulate alpha * A * B into C
	//
	// We explicitly control the traversal order to improve locality:
	//   - outer:  i (rows of C and A)
	//   - middle: k (columns of A / rows of B)
	//   - inner:  j (columns of C and B, contiguous in memory)
	//
	// We use a single multi-structure traverser over (C, A, B) and nest
	// for_dims to obtain the desired loop nest.
	// ---------------------------------------------------------------------
	traverser(C, A, B).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has 'i' fixed; remaining varying dims here are 'k' and 'j'

		// Loop over k for the current row i
		trav_i.template for_dims<'k'>([=](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed; remaining varying dim is 'j'

			// Load A[i,k] once and pre-scale by alpha; this value is reused
			// for all j in the innermost loop, reducing multiplications.
			const num_t a_ik    = A[trav_ik];
			const num_t scaledA = alpha * a_ik;

			// For all j: C[i,j] += scaledA * B[k,j]
			// This innermost loop walks contiguous memory in both C and B:
			//  - C: dims 'i','j'  => j contiguous
			//  - B: dims 'k','j'  => j contiguous
			trav_ik.template for_dims<'j'>([=](auto trav_ijk) {
				C[trav_ijk] += scaledA * B[trav_ijk];
			});
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;

	// scalars
	num_t alpha;
	num_t beta;

	// lengths proto-structure (applied to all matrices)
	auto set_lengths =
		noarr::set_length<'i'>(ni)
		^ noarr::set_length<'j'>(nj)
		^ noarr::set_length<'k'>(nk);

	// bags for C, A, B with appropriate layouts
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths); // i x j
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths); // i x k
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths); // k x j

	// initialize arrays
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gemm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// output to prevent dead-code elimination (similar role as print_array/polybench_prevent_dce)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
